#:sdk Microsoft.NET.Sdk.Web #:package MessagePack@2.5.122 #:package Microsoft.Extensions.ObjectPool@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using MessagePack; using Microsoft.Extensions.ObjectPool;  public class ThreadSafeMemoryPoolSerializer : IDisposable {     private readonly ObjectPool<byte[]> _bufferPool;     private readonly ObjectPool<MessagePackWriter> _writerPool;      public ThreadSafeMemoryPoolSerializer()     {         var bufferPolicy = new DefaultPooledObjectPolicy<byte[]>();         _bufferPool = new DefaultObjectPool<byte[]>(bufferPolicy, Environment.ProcessorCount * 2);          var writerPolicy = new MessagePackWriterPooledObjectPolicy();         _writerPool = new DefaultObjectPool<MessagePackWriter>(writerPolicy);     }      public byte[] Serialize<T>(T value)     {         var buffer = _bufferPool.Get();         try         {             var writer = _writerPool.Get();             try             {                 writer.Reset(buffer);                 MessagePackSerializer.Serialize(ref writer, value);                 return buffer[..writer.BytesWritten];             }             finally             {                 _writerPool.Return(writer);             }         }         finally         {             _bufferPool.Return(buffer);         }     }      public void Dispose()     {         // 清理资源     } }  internal class MessagePackWriterPooledObjectPolicy : IPooledObjectPolicy<MessagePackWriter> {     public MessagePackWriter Create()     {         return new MessagePackWriter(Array.Empty<byte>());     }      public bool Return(MessagePackWriter obj)     {         return true;     } }
